insert into public.exercises
  (nombre, grupo_muscular, equipo, instrucciones, imagenes, origen, origen_id)
values
  ('Press de banca con barra', 'Pecho', 'Barra', 'Acostate en el banco plano con los pies firmes en el piso. Tomá la barra con un agarre algo más ancho que los hombros y bajala controlada hasta rozar el pecho. Empujá hacia arriba hasta extender los brazos sin bloquear los codos.', array['importados/Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'importados/Barbell_Bench_Press_-_Medium_Grip/1.jpg'], 'importado', 'Barbell_Bench_Press_-_Medium_Grip'),
  ('Press inclinado con barra', 'Pecho', 'Barra', 'Acostate en un banco inclinado (30-45°). Bajá la barra controlada hasta la parte alta del pecho y empujala hacia arriba hasta extender los brazos. Mantené los omóplatos juntos y apoyados en el banco.', array['importados/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg', 'importados/Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg'], 'importado', 'Barbell_Incline_Bench_Press_-_Medium_Grip'),
  ('Press declinado con barra', 'Pecho', 'Barra', 'Acostate en el banco declinado con las piernas trabadas. Bajá la barra hasta la parte baja del pecho y empujala hacia arriba hasta extender los brazos. Mové la barra lento y controlado.', array['importados/Decline_Barbell_Bench_Press/0.jpg', 'importados/Decline_Barbell_Bench_Press/1.jpg'], 'importado', 'Decline_Barbell_Bench_Press'),
  ('Press de banca con mancuernas', 'Pecho', 'Mancuernas', 'Acostate en el banco plano con una mancuerna en cada mano a la altura del pecho. Empujá hacia arriba hasta extender los brazos, juntando un poco las mancuernas arriba. Bajalas controladas hasta sentir el estiramiento en el pecho.', array['importados/Dumbbell_Bench_Press/0.jpg', 'importados/Dumbbell_Bench_Press/1.jpg'], 'importado', 'Dumbbell_Bench_Press'),
  ('Press inclinado con mancuernas', 'Pecho', 'Mancuernas', 'En un banco inclinado, sostené las mancuernas a los costados del pecho. Empujalas hacia arriba hasta extender los brazos y bajalas lento a la posición inicial.', array['importados/Incline_Dumbbell_Press/0.jpg', 'importados/Incline_Dumbbell_Press/1.jpg'], 'importado', 'Incline_Dumbbell_Press'),
  ('Press declinado con mancuernas', 'Pecho', 'Mancuernas', 'Acostate en el banco declinado con las piernas trabadas y una mancuerna en cada mano. Empujalas hacia arriba hasta extender los brazos y bajalas controladas hasta la parte baja del pecho.', array['importados/Decline_Dumbbell_Bench_Press/0.jpg', 'importados/Decline_Dumbbell_Bench_Press/1.jpg'], 'importado', 'Decline_Dumbbell_Bench_Press'),
  ('Aperturas con mancuernas', 'Pecho', 'Mancuernas', 'Acostate en el banco plano con las mancuernas arriba del pecho y los codos apenas flexionados. Abrí los brazos en arco hasta sentir el estiramiento en el pecho y volvé a juntarlas arriba con el mismo recorrido.', array['importados/Dumbbell_Flyes/0.jpg', 'importados/Dumbbell_Flyes/1.jpg'], 'importado', 'Dumbbell_Flyes'),
  ('Aperturas inclinadas con mancuernas', 'Pecho', 'Mancuernas', 'En un banco inclinado, con las mancuernas arriba y los codos apenas flexionados, abrí los brazos en arco hasta sentir el estiramiento. Volvé a juntarlas arriba sin cambiar el ángulo de los codos.', array['importados/Incline_Dumbbell_Flyes/0.jpg', 'importados/Incline_Dumbbell_Flyes/1.jpg'], 'importado', 'Incline_Dumbbell_Flyes'),
  ('Aperturas en máquina (peck deck)', 'Pecho', 'Máquina', 'Sentate con la espalda apoyada y los brazos en las almohadillas o manijas a la altura del pecho. Juntá los brazos adelante apretando el pecho y volvé lento a la posición inicial.', array['importados/Butterfly/0.jpg', 'importados/Butterfly/1.jpg'], 'importado', 'Butterfly'),
  ('Cruce de poleas', 'Pecho', 'Polea', 'Parate en el centro con una manija de cada polea alta y un pie adelante. Con los codos apenas flexionados, llevá las manos hacia abajo y adelante hasta juntarlas frente a la cadera. Volvé controlado.', array['importados/Cable_Crossover/0.jpg', 'importados/Cable_Crossover/1.jpg'], 'importado', 'Cable_Crossover'),
  ('Cruce de poleas desde abajo', 'Pecho', 'Polea', 'Con las poleas abajo y una manija en cada mano, llevá los brazos hacia arriba y adelante hasta juntar las manos a la altura de los hombros. Bajá lento sin perder la tensión.', array['importados/Low_Cable_Crossover/0.jpg', 'importados/Low_Cable_Crossover/1.jpg'], 'importado', 'Low_Cable_Crossover'),
  ('Press de pecho en máquina', 'Pecho', 'Máquina', 'Ajustá el asiento para que las manijas queden a la altura del pecho. Empujá hasta extender los brazos sin bloquear los codos y volvé controlado.', array['importados/Machine_Bench_Press/0.jpg', 'importados/Machine_Bench_Press/1.jpg'], 'importado', 'Machine_Bench_Press'),
  ('Press inclinado en máquina', 'Pecho', 'Máquina', 'Sentate con la espalda apoyada y las manijas a la altura de la parte alta del pecho. Empujá hacia arriba y adelante hasta extender los brazos y volvé lento.', array['importados/Leverage_Incline_Chest_Press/0.jpg', 'importados/Leverage_Incline_Chest_Press/1.jpg'], 'importado', 'Leverage_Incline_Chest_Press'),
  ('Press de banca en máquina Smith', 'Pecho', 'Máquina', 'Acostate en un banco plano debajo de la barra de la Smith. Destrabala, bajala controlada hasta el pecho y empujá hasta extender los brazos. Trabala al terminar.', array['importados/Smith_Machine_Bench_Press/0.jpg', 'importados/Smith_Machine_Bench_Press/1.jpg'], 'importado', 'Smith_Machine_Bench_Press'),
  ('Flexiones de brazos', 'Pecho', 'Peso corporal', 'Apoyá las manos un poco más abiertas que los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Bajá el pecho hasta casi tocar el piso y empujá hasta extender los brazos.', array['importados/Pushups/0.jpg', 'importados/Pushups/1.jpg'], 'importado', 'Pushups'),
  ('Flexiones con pies elevados', 'Pecho', 'Peso corporal', 'Igual que una flexión común, pero con los pies apoyados en un banco o cajón. Mantené el cuerpo recto, bajá el pecho hacia el piso y empujá hasta extender los brazos.', array['importados/Push-Ups_With_Feet_Elevated/0.jpg', 'importados/Push-Ups_With_Feet_Elevated/1.jpg'], 'importado', 'Push-Ups_With_Feet_Elevated'),
  ('Flexiones inclinadas', 'Pecho', 'Peso corporal', 'Apoyá las manos en un banco o barra elevada y el cuerpo recto. Bajá el pecho hacia el apoyo y empujá hasta extender los brazos. Es la versión más fácil de la flexión.', array['importados/Incline_Push-Up/0.jpg', 'importados/Incline_Push-Up/1.jpg'], 'importado', 'Incline_Push-Up'),
  ('Fondos en paralelas (pecho)', 'Pecho', 'Peso corporal', 'Sostenete en las paralelas con los brazos extendidos. Inclinate un poco hacia adelante y bajá flexionando los codos hasta sentir el estiramiento en el pecho. Empujá hasta volver arriba.', array['importados/Dips_-_Chest_Version/0.jpg', 'importados/Dips_-_Chest_Version/1.jpg'], 'importado', 'Dips_-_Chest_Version'),
  ('Pullover con mancuerna', 'Pecho', 'Mancuernas', 'Acostate en el banco sosteniendo una mancuerna con las dos manos arriba del pecho. Con los brazos casi rectos, llevala hacia atrás por encima de la cabeza hasta sentir el estiramiento y volvé a la posición inicial.', array['importados/Straight-Arm_Dumbbell_Pullover/0.jpg', 'importados/Straight-Arm_Dumbbell_Pullover/1.jpg'], 'importado', 'Straight-Arm_Dumbbell_Pullover'),
  ('Dominadas', 'Espalda', 'Peso corporal', 'Colgate de la barra con agarre prono, un poco más ancho que los hombros. Subí tirando con la espalda hasta pasar el mentón por encima de la barra y bajá controlado hasta extender los brazos.', array['importados/Pullups/0.jpg', 'importados/Pullups/1.jpg'], 'importado', 'Pullups'),
  ('Dominadas supinas', 'Espalda', 'Peso corporal', 'Colgate de la barra con las palmas hacia vos, al ancho de los hombros. Subí hasta pasar el mentón por encima de la barra y bajá lento hasta extender los brazos.', array['importados/Chin-Up/0.jpg', 'importados/Chin-Up/1.jpg'], 'importado', 'Chin-Up'),
  ('Jalón al pecho agarre ancho', 'Espalda', 'Polea', 'Sentate con los muslos trabados y tomá la barra con agarre ancho. Tirá la barra hacia la parte alta del pecho llevando los codos hacia abajo y atrás. Subí controlado hasta extender los brazos.', array['importados/Wide-Grip_Lat_Pulldown/0.jpg', 'importados/Wide-Grip_Lat_Pulldown/1.jpg'], 'importado', 'Wide-Grip_Lat_Pulldown'),
  ('Jalón al pecho agarre cerrado', 'Espalda', 'Polea', 'Tomá la barra con las manos juntas, sentado con los muslos trabados. Tirá hacia el pecho inclinándote apenas hacia atrás y volvé lento arriba.', array['importados/Close-Grip_Front_Lat_Pulldown/0.jpg', 'importados/Close-Grip_Front_Lat_Pulldown/1.jpg'], 'importado', 'Close-Grip_Front_Lat_Pulldown'),
  ('Jalón con triángulo', 'Espalda', 'Polea', 'Enganchá el triángulo en la polea alta y sentate con los muslos trabados. Tirá hacia el pecho llevando los codos pegados al cuerpo y volvé controlado.', array['importados/V-Bar_Pulldown/0.jpg', 'importados/V-Bar_Pulldown/1.jpg'], 'importado', 'V-Bar_Pulldown'),
  ('Jalón con agarre supino', 'Espalda', 'Polea', 'Tomá la barra con las palmas hacia vos, al ancho de los hombros. Tirá hacia la parte alta del pecho y subí controlado hasta extender los brazos.', array['importados/Underhand_Cable_Pulldowns/0.jpg', 'importados/Underhand_Cable_Pulldowns/1.jpg'], 'importado', 'Underhand_Cable_Pulldowns'),
  ('Jalón a una mano', 'Espalda', 'Polea', 'Con una manija en la polea alta, tirá con un brazo llevando el codo hacia abajo y al costado del cuerpo. Volvé controlado y hacé todas las repeticiones antes de cambiar de lado.', array['importados/One_Arm_Lat_Pulldown/0.jpg', 'importados/One_Arm_Lat_Pulldown/1.jpg'], 'importado', 'One_Arm_Lat_Pulldown'),
  ('Pullover en polea con brazos rectos', 'Espalda', 'Polea', 'De pie frente a la polea alta, tomá la barra con los brazos casi rectos. Llevala hacia abajo hasta los muslos apretando la espalda y volvé lento hasta la altura de los ojos.', array['importados/Straight-Arm_Pulldown/0.jpg', 'importados/Straight-Arm_Pulldown/1.jpg'], 'importado', 'Straight-Arm_Pulldown'),
  ('Remo sentado en polea', 'Espalda', 'Polea', 'Sentate con los pies apoyados y la espalda recta, tomando el triángulo con los brazos extendidos. Tirá hacia el abdomen juntando los omóplatos y volvé controlado sin encorvarte.', array['importados/Seated_Cable_Rows/0.jpg', 'importados/Seated_Cable_Rows/1.jpg'], 'importado', 'Seated_Cable_Rows'),
  ('Remo a una mano en polea', 'Espalda', 'Polea', 'Sentado frente a la polea baja, tomá una manija con una mano. Tirá llevando el codo hacia atrás pegado al cuerpo y volvé estirando el brazo. Repetí con el otro lado.', array['importados/Seated_One-arm_Cable_Pulley_Rows/0.jpg', 'importados/Seated_One-arm_Cable_Pulley_Rows/1.jpg'], 'importado', 'Seated_One-arm_Cable_Pulley_Rows'),
  ('Remo con barra', 'Espalda', 'Barra', 'Con las rodillas apenas flexionadas, inclinate hacia adelante con la espalda recta y la barra colgando. Tirá la barra hacia el abdomen juntando los omóplatos y bajala controlada.', array['importados/Bent_Over_Barbell_Row/0.jpg', 'importados/Bent_Over_Barbell_Row/1.jpg'], 'importado', 'Bent_Over_Barbell_Row'),
  ('Remo con barra agarre supino', 'Espalda', 'Barra', 'Igual que el remo con barra pero con las palmas hacia adelante. Con la espalda recta e inclinada, tirá la barra hacia el abdomen y bajala lento.', array['importados/Reverse_Grip_Bent-Over_Rows/0.jpg', 'importados/Reverse_Grip_Bent-Over_Rows/1.jpg'], 'importado', 'Reverse_Grip_Bent-Over_Rows'),
  ('Remo con mancuerna a una mano', 'Espalda', 'Mancuernas', 'Apoyá una rodilla y una mano en el banco, con la espalda recta. Con la otra mano, tirá la mancuerna hacia la cadera llevando el codo hacia atrás y bajala controlada.', array['importados/One-Arm_Dumbbell_Row/0.jpg', 'importados/One-Arm_Dumbbell_Row/1.jpg'], 'importado', 'One-Arm_Dumbbell_Row'),
  ('Remo con dos mancuernas', 'Espalda', 'Mancuernas', 'Inclinate hacia adelante con la espalda recta y una mancuerna en cada mano. Tirá las dos hacia el abdomen juntando los omóplatos y bajalas lento.', array['importados/Bent_Over_Two-Dumbbell_Row/0.jpg', 'importados/Bent_Over_Two-Dumbbell_Row/1.jpg'], 'importado', 'Bent_Over_Two-Dumbbell_Row'),
  ('Remo con mancuernas en banco inclinado', 'Espalda', 'Mancuernas', 'Acostate boca abajo en un banco inclinado con una mancuerna en cada mano. Tirá las mancuernas hacia atrás llevando los codos hacia arriba y bajalas controladas.', array['importados/Dumbbell_Incline_Row/0.jpg', 'importados/Dumbbell_Incline_Row/1.jpg'], 'importado', 'Dumbbell_Incline_Row'),
  ('Remo en T', 'Espalda', 'Barra', 'Con la barra trabada en un extremo, parate encima con las rodillas apenas flexionadas y la espalda recta. Tirá la manija hacia el pecho y bajala controlada.', array['importados/T-Bar_Row_with_Handle/0.jpg', 'importados/T-Bar_Row_with_Handle/1.jpg'], 'importado', 'T-Bar_Row_with_Handle'),
  ('Remo en T con apoyo de pecho', 'Espalda', 'Máquina', 'Acostate boca abajo en la máquina con el pecho apoyado. Tirá las manijas hacia arriba juntando los omóplatos y bajalas lento.', array['importados/Lying_T-Bar_Row/0.jpg', 'importados/Lying_T-Bar_Row/1.jpg'], 'importado', 'Lying_T-Bar_Row'),
  ('Remo alto en máquina', 'Espalda', 'Máquina', 'Sentate con el pecho contra el apoyo y tomá las manijas altas. Tirá hacia abajo y atrás llevando los codos al costado del cuerpo y volvé controlado.', array['importados/Leverage_High_Row/0.jpg', 'importados/Leverage_High_Row/1.jpg'], 'importado', 'Leverage_High_Row'),
  ('Remo en máquina', 'Espalda', 'Máquina', 'Sentate con el pecho apoyado y tomá las manijas. Tirá hacia atrás juntando los omóplatos y volvé lento hasta estirar los brazos.', array['importados/Leverage_Iso_Row/0.jpg', 'importados/Leverage_Iso_Row/1.jpg'], 'importado', 'Leverage_Iso_Row'),
  ('Peso muerto con barra', 'Espalda', 'Barra', 'Con los pies al ancho de la cadera y la barra sobre la mitad del pie, flexioná cadera y rodillas y tomá la barra. Con la espalda recta, levantala empujando el piso hasta quedar erguido. Bajala controlada con el mismo recorrido.', array['importados/Barbell_Deadlift/0.jpg', 'importados/Barbell_Deadlift/1.jpg'], 'importado', 'Barbell_Deadlift'),
  ('Hiperextensiones lumbares', 'Espalda', 'Peso corporal', 'Ubicate en el banco de hiperextensiones con la cadera apoyada y los talones trabados. Bajá el torso con la espalda recta y subí hasta quedar alineado con las piernas, sin pasarte hacia atrás.', array['importados/Hyperextensions_Back_Extensions/0.jpg', 'importados/Hyperextensions_Back_Extensions/1.jpg'], 'importado', 'Hyperextensions_Back_Extensions'),
  ('Encogimientos con barra', 'Espalda', 'Barra', 'De pie con la barra frente a los muslos y los brazos extendidos, subí los hombros hacia las orejas lo más alto que puedas. Sostené un segundo y bajá lento.', array['importados/Barbell_Shrug/0.jpg', 'importados/Barbell_Shrug/1.jpg'], 'importado', 'Barbell_Shrug'),
  ('Encogimientos con mancuernas', 'Espalda', 'Mancuernas', 'De pie con una mancuerna en cada mano a los costados, subí los hombros hacia las orejas. Sostené un segundo arriba y bajá controlado.', array['importados/Dumbbell_Shrug/0.jpg', 'importados/Dumbbell_Shrug/1.jpg'], 'importado', 'Dumbbell_Shrug'),
  ('Press militar de pie con barra', 'Hombros', 'Barra', 'De pie, con la barra apoyada adelante a la altura de los hombros, empujala por encima de la cabeza hasta extender los brazos. Bajala controlada sin arquear la zona lumbar.', array['importados/Standing_Military_Press/0.jpg', 'importados/Standing_Military_Press/1.jpg'], 'importado', 'Standing_Military_Press'),
  ('Press militar sentado con barra', 'Hombros', 'Barra', 'Sentado con la espalda apoyada, sostené la barra a la altura de los hombros. Empujala hacia arriba hasta extender los brazos y bajala lento hasta el mentón.', array['importados/Seated_Barbell_Military_Press/0.jpg', 'importados/Seated_Barbell_Military_Press/1.jpg'], 'importado', 'Seated_Barbell_Military_Press'),
  ('Press de hombros con mancuernas', 'Hombros', 'Mancuernas', 'Sentado con la espalda apoyada, sostené las mancuernas a la altura de los hombros. Empujalas hacia arriba hasta extender los brazos y bajalas controladas.', array['importados/Dumbbell_Shoulder_Press/0.jpg', 'importados/Dumbbell_Shoulder_Press/1.jpg'], 'importado', 'Dumbbell_Shoulder_Press'),
  ('Press Arnold', 'Hombros', 'Mancuernas', 'Empezá con las mancuernas frente a la cara y las palmas hacia vos. Mientras empujás hacia arriba, girá las muñecas hasta que las palmas miren hacia adelante. Bajá haciendo el giro inverso.', array['importados/Arnold_Dumbbell_Press/0.jpg', 'importados/Arnold_Dumbbell_Press/1.jpg'], 'importado', 'Arnold_Dumbbell_Press'),
  ('Press de hombros en máquina', 'Hombros', 'Máquina', 'Ajustá el asiento para que las manijas queden a la altura de los hombros. Empujá hacia arriba hasta extender los brazos y volvé controlado.', array['importados/Machine_Shoulder_Military_Press/0.jpg', 'importados/Machine_Shoulder_Military_Press/1.jpg'], 'importado', 'Machine_Shoulder_Military_Press'),
  ('Press de hombros en máquina Smith', 'Hombros', 'Máquina', 'Sentado en un banco debajo de la barra de la Smith, destrabala a la altura de los hombros. Empujá hacia arriba hasta extender los brazos y bajá lento.', array['importados/Smith_Machine_Overhead_Shoulder_Press/0.jpg', 'importados/Smith_Machine_Overhead_Shoulder_Press/1.jpg'], 'importado', 'Smith_Machine_Overhead_Shoulder_Press'),
  ('Elevaciones laterales con mancuernas', 'Hombros', 'Mancuernas', 'De pie con una mancuerna en cada mano a los costados, elevá los brazos hacia los lados con los codos apenas flexionados hasta la altura de los hombros. Bajá lento.', array['importados/Side_Lateral_Raise/0.jpg', 'importados/Side_Lateral_Raise/1.jpg'], 'importado', 'Side_Lateral_Raise'),
  ('Elevación lateral en polea', 'Hombros', 'Polea', 'De costado a la polea baja, tomá la manija con la mano más alejada. Elevá el brazo hacia el costado hasta la altura del hombro y bajalo controlado.', array['importados/Standing_Low-Pulley_Deltoid_Raise/0.jpg', 'importados/Standing_Low-Pulley_Deltoid_Raise/1.jpg'], 'importado', 'Standing_Low-Pulley_Deltoid_Raise'),
  ('Elevaciones frontales con mancuernas', 'Hombros', 'Mancuernas', 'De pie con las mancuernas frente a los muslos, elevá los brazos hacia adelante hasta la altura de los hombros. Bajalos lento sin balancear el cuerpo.', array['importados/Front_Dumbbell_Raise/0.jpg', 'importados/Front_Dumbbell_Raise/1.jpg'], 'importado', 'Front_Dumbbell_Raise'),
  ('Elevación frontal en polea', 'Hombros', 'Polea', 'De espaldas a la polea baja, con la manija entre las piernas, elevá el brazo hacia adelante hasta la altura del hombro. Bajalo controlado.', array['importados/Front_Cable_Raise/0.jpg', 'importados/Front_Cable_Raise/1.jpg'], 'importado', 'Front_Cable_Raise'),
  ('Pájaros con mancuernas', 'Hombros', 'Mancuernas', 'Inclinate hacia adelante con la espalda recta y las mancuernas colgando. Abrí los brazos hacia los costados con los codos apenas flexionados, juntando los omóplatos. Bajá lento.', array['importados/Reverse_Flyes/0.jpg', 'importados/Reverse_Flyes/1.jpg'], 'importado', 'Reverse_Flyes'),
  ('Pájaros sentado', 'Hombros', 'Mancuernas', 'Sentado en el borde del banco, inclinate con el pecho cerca de los muslos y las mancuernas debajo de las piernas. Abrí los brazos hacia los costados hasta la altura de los hombros y bajá controlado.', array['importados/Seated_Bent-Over_Rear_Delt_Raise/0.jpg', 'importados/Seated_Bent-Over_Rear_Delt_Raise/1.jpg'], 'importado', 'Seated_Bent-Over_Rear_Delt_Raise'),
  ('Aperturas invertidas en máquina', 'Hombros', 'Máquina', 'Sentate mirando hacia el respaldo de la máquina de aperturas y tomá las manijas. Llevá los brazos hacia atrás abriéndolos y volvé lento.', array['importados/Reverse_Machine_Flyes/0.jpg', 'importados/Reverse_Machine_Flyes/1.jpg'], 'importado', 'Reverse_Machine_Flyes'),
  ('Vuelos posteriores en polea', 'Hombros', 'Polea', 'Entre dos poleas altas, tomá cada cable con la mano contraria (cruzados). Abrí los brazos hacia atrás a la altura de los hombros y volvé controlado.', array['importados/Cable_Rear_Delt_Fly/0.jpg', 'importados/Cable_Rear_Delt_Fly/1.jpg'], 'importado', 'Cable_Rear_Delt_Fly'),
  ('Face pull en polea', 'Hombros', 'Polea', 'Con la soga en la polea a la altura de la cara, tirá hacia el rostro separando las manos y llevando los codos hacia afuera y arriba. Volvé lento.', array['importados/Face_Pull/0.jpg', 'importados/Face_Pull/1.jpg'], 'importado', 'Face_Pull'),
  ('Remo al mentón con barra', 'Hombros', 'Barra', 'De pie con la barra frente a los muslos y agarre cerrado, subila pegada al cuerpo hasta la altura del pecho, con los codos por encima de las manos. Bajala controlada.', array['importados/Upright_Barbell_Row/0.jpg', 'importados/Upright_Barbell_Row/1.jpg'], 'importado', 'Upright_Barbell_Row'),
  ('Remo al mentón con mancuernas', 'Hombros', 'Mancuernas', 'De pie con las mancuernas frente a los muslos, subilas pegadas al cuerpo llevando los codos hacia arriba hasta la altura del pecho. Bajá lento.', array['importados/Standing_Dumbbell_Upright_Row/0.jpg', 'importados/Standing_Dumbbell_Upright_Row/1.jpg'], 'importado', 'Standing_Dumbbell_Upright_Row'),
  ('Rotación externa en polea', 'Hombros', 'Polea', 'De costado a la polea a la altura del codo, con el codo pegado al cuerpo y flexionado a 90°, girá el antebrazo hacia afuera. Volvé lento. Sirve para cuidar el hombro.', array['importados/External_Rotation_with_Cable/0.jpg', 'importados/External_Rotation_with_Cable/1.jpg'], 'importado', 'External_Rotation_with_Cable'),
  ('Curl de bíceps con barra', 'Bíceps', 'Barra', 'De pie con la barra en agarre supino y los codos pegados al cuerpo, subila flexionando los codos hasta los hombros. Bajala lento sin balancear el torso.', array['importados/Barbell_Curl/0.jpg', 'importados/Barbell_Curl/1.jpg'], 'importado', 'Barbell_Curl'),
  ('Curl con barra Z', 'Bíceps', 'Barra', 'Tomá la barra Z por las partes anguladas, con los codos pegados al cuerpo. Subila flexionando los codos y bajala controlada.', array['importados/EZ-Bar_Curl/0.jpg', 'importados/EZ-Bar_Curl/1.jpg'], 'importado', 'EZ-Bar_Curl'),
  ('Curl de bíceps con mancuernas', 'Bíceps', 'Mancuernas', 'De pie con una mancuerna en cada mano y las palmas hacia adelante, subilas flexionando los codos sin moverlos del costado del cuerpo. Bajá lento.', array['importados/Dumbbell_Bicep_Curl/0.jpg', 'importados/Dumbbell_Bicep_Curl/1.jpg'], 'importado', 'Dumbbell_Bicep_Curl'),
  ('Curl alternado con mancuernas', 'Bíceps', 'Mancuernas', 'De pie con una mancuerna en cada mano, subí una girando la palma hacia arriba mientras flexionás el codo. Bajala y repetí con el otro brazo.', array['importados/Dumbbell_Alternate_Bicep_Curl/0.jpg', 'importados/Dumbbell_Alternate_Bicep_Curl/1.jpg'], 'importado', 'Dumbbell_Alternate_Bicep_Curl'),
  ('Curl martillo', 'Bíceps', 'Mancuernas', 'De pie con las mancuernas a los costados y las palmas mirándose, subilas flexionando los codos sin girar las muñecas. Bajalas controladas.', array['importados/Hammer_Curls/0.jpg', 'importados/Hammer_Curls/1.jpg'], 'importado', 'Hammer_Curls'),
  ('Curl en banco inclinado', 'Bíceps', 'Mancuernas', 'Sentado en un banco inclinado con los brazos colgando, subí las mancuernas flexionando los codos sin moverlos hacia adelante. Bajalas lento hasta estirar los brazos.', array['importados/Incline_Dumbbell_Curl/0.jpg', 'importados/Incline_Dumbbell_Curl/1.jpg'], 'importado', 'Incline_Dumbbell_Curl'),
  ('Curl concentrado', 'Bíceps', 'Mancuernas', 'Sentado, apoyá el codo en la cara interna del muslo con la mancuerna colgando. Subila flexionando el codo y bajala lento. Hacé todas las repeticiones y cambiá de brazo.', array['importados/Concentration_Curls/0.jpg', 'importados/Concentration_Curls/1.jpg'], 'importado', 'Concentration_Curls'),
  ('Curl en banco Scott con barra', 'Bíceps', 'Barra', 'Apoyá la parte de atrás de los brazos en el banco Scott y tomá la barra con agarre supino. Subila flexionando los codos y bajala controlada sin estirar de golpe.', array['importados/Preacher_Curl/0.jpg', 'importados/Preacher_Curl/1.jpg'], 'importado', 'Preacher_Curl'),
  ('Curl Scott en máquina', 'Bíceps', 'Máquina', 'Sentate con los brazos apoyados en la almohadilla y tomá las manijas. Flexioná los codos hasta arriba y bajá lento.', array['importados/Machine_Preacher_Curls/0.jpg', 'importados/Machine_Preacher_Curls/1.jpg'], 'importado', 'Machine_Preacher_Curls'),
  ('Curl de bíceps en polea', 'Bíceps', 'Polea', 'De pie frente a la polea baja con la barra en agarre supino, subila flexionando los codos pegados al cuerpo. Bajá controlado.', array['importados/Standing_Biceps_Cable_Curl/0.jpg', 'importados/Standing_Biceps_Cable_Curl/1.jpg'], 'importado', 'Standing_Biceps_Cable_Curl'),
  ('Curl martillo en polea con soga', 'Bíceps', 'Polea', 'Con la soga en la polea baja y las palmas mirándose, subila flexionando los codos pegados al cuerpo. Bajala lento.', array['importados/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg', 'importados/Cable_Hammer_Curls_-_Rope_Attachment/1.jpg'], 'importado', 'Cable_Hammer_Curls_-_Rope_Attachment'),
  ('Curl araña', 'Bíceps', 'Barra', 'Acostate boca abajo en un banco inclinado con los brazos colgando del otro lado y la barra en las manos. Subila flexionando los codos y bajala lento.', array['importados/Spider_Curl/0.jpg', 'importados/Spider_Curl/1.jpg'], 'importado', 'Spider_Curl'),
  ('Extensión de tríceps en polea', 'Tríceps', 'Polea', 'De pie frente a la polea alta con la barra en las manos y los codos pegados al cuerpo, empujá hacia abajo hasta extender los brazos. Volvé controlado sin mover los codos.', array['importados/Triceps_Pushdown/0.jpg', 'importados/Triceps_Pushdown/1.jpg'], 'importado', 'Triceps_Pushdown'),
  ('Extensión de tríceps en polea con soga', 'Tríceps', 'Polea', 'Con la soga en la polea alta y los codos pegados al cuerpo, empujá hacia abajo y separá las manos al final del movimiento. Volvé lento.', array['importados/Triceps_Pushdown_-_Rope_Attachment/0.jpg', 'importados/Triceps_Pushdown_-_Rope_Attachment/1.jpg'], 'importado', 'Triceps_Pushdown_-_Rope_Attachment'),
  ('Extensión en polea agarre invertido', 'Tríceps', 'Polea', 'Tomá la barra de la polea alta con las palmas hacia arriba. Con los codos pegados al cuerpo, empujá hacia abajo hasta extender los brazos y volvé controlado.', array['importados/Reverse_Grip_Triceps_Pushdown/0.jpg', 'importados/Reverse_Grip_Triceps_Pushdown/1.jpg'], 'importado', 'Reverse_Grip_Triceps_Pushdown'),
  ('Extensión de tríceps con soga por encima de la cabeza', 'Tríceps', 'Polea', 'De espaldas a la polea con la soga detrás de la cabeza, extendé los brazos hacia adelante y arriba sin mover los codos. Volvé lento hasta sentir el estiramiento.', array['importados/Triceps_Overhead_Extension_with_Rope/0.jpg', 'importados/Triceps_Overhead_Extension_with_Rope/1.jpg'], 'importado', 'Triceps_Overhead_Extension_with_Rope'),
  ('Press francés con barra Z', 'Tríceps', 'Barra', 'Acostate en el banco con la barra Z arriba del pecho y los brazos extendidos. Flexioná los codos bajando la barra hacia la frente sin mover los brazos y volvé a extenderlos.', array['importados/EZ-Bar_Skullcrusher/0.jpg', 'importados/EZ-Bar_Skullcrusher/1.jpg'], 'importado', 'EZ-Bar_Skullcrusher'),
  ('Press francés con mancuernas', 'Tríceps', 'Mancuernas', 'Acostate en el banco con una mancuerna en cada mano y los brazos extendidos. Bajá las mancuernas a los costados de la cabeza flexionando los codos y volvé a extenderlos.', array['importados/Lying_Dumbbell_Tricep_Extension/0.jpg', 'importados/Lying_Dumbbell_Tricep_Extension/1.jpg'], 'importado', 'Lying_Dumbbell_Tricep_Extension'),
  ('Extensión de tríceps con mancuerna por encima de la cabeza', 'Tríceps', 'Mancuernas', 'De pie o sentado, sostené una mancuerna con las dos manos por encima de la cabeza. Bajala por detrás de la cabeza flexionando los codos y volvé a extender los brazos.', array['importados/Standing_Dumbbell_Triceps_Extension/0.jpg', 'importados/Standing_Dumbbell_Triceps_Extension/1.jpg'], 'importado', 'Standing_Dumbbell_Triceps_Extension'),
  ('Patada de tríceps con mancuerna', 'Tríceps', 'Mancuernas', 'Inclinado con una mano y una rodilla en el banco, llevá el codo pegado al cuerpo a 90°. Extendé el brazo hacia atrás hasta dejarlo recto y volvé controlado.', array['importados/Tricep_Dumbbell_Kickback/0.jpg', 'importados/Tricep_Dumbbell_Kickback/1.jpg'], 'importado', 'Tricep_Dumbbell_Kickback'),
  ('Press de banca agarre cerrado', 'Tríceps', 'Barra', 'Acostate en el banco y tomá la barra con las manos al ancho de los hombros. Bajala hasta el pecho con los codos pegados al cuerpo y empujá hasta extender los brazos.', array['importados/Close-Grip_Barbell_Bench_Press/0.jpg', 'importados/Close-Grip_Barbell_Bench_Press/1.jpg'], 'importado', 'Close-Grip_Barbell_Bench_Press'),
  ('Fondos en banco', 'Tríceps', 'Peso corporal', 'Apoyá las manos en el borde de un banco detrás tuyo y los talones en el piso. Bajá el cuerpo flexionando los codos hasta 90° y empujá hasta extender los brazos.', array['importados/Bench_Dips/0.jpg', 'importados/Bench_Dips/1.jpg'], 'importado', 'Bench_Dips'),
  ('Fondos en paralelas (tríceps)', 'Tríceps', 'Peso corporal', 'Sostenete en las paralelas con el cuerpo vertical. Bajá flexionando los codos pegados al cuerpo hasta 90° y empujá hasta extender los brazos.', array['importados/Dips_-_Triceps_Version/0.jpg', 'importados/Dips_-_Triceps_Version/1.jpg'], 'importado', 'Dips_-_Triceps_Version'),
  ('Fondos en máquina', 'Tríceps', 'Máquina', 'Sentate en la máquina y tomá las manijas a los costados. Empujá hacia abajo hasta extender los brazos y volvé controlado.', array['importados/Dip_Machine/0.jpg', 'importados/Dip_Machine/1.jpg'], 'importado', 'Dip_Machine'),
  ('Extensión de tríceps en máquina', 'Tríceps', 'Máquina', 'Sentate con los brazos apoyados en la almohadilla y tomá las manijas. Extendé los codos hasta estirar los brazos y volvé lento.', array['importados/Machine_Triceps_Extension/0.jpg', 'importados/Machine_Triceps_Extension/1.jpg'], 'importado', 'Machine_Triceps_Extension'),
  ('Flexiones cerradas', 'Tríceps', 'Peso corporal', 'En posición de flexión, apoyá las manos juntas debajo del pecho. Bajá con los codos pegados al cuerpo y empujá hasta extender los brazos.', array['importados/Push-Ups_-_Close_Triceps_Position/0.jpg', 'importados/Push-Ups_-_Close_Triceps_Position/1.jpg'], 'importado', 'Push-Ups_-_Close_Triceps_Position'),
  ('Curl de muñeca con barra', 'Antebrazos', 'Barra', 'Arrodillado frente a un banco, apoyá los antebrazos con las palmas hacia arriba y las muñecas afuera. Dejá bajar la barra doblando las muñecas y subila flexionándolas.', array['importados/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg', 'importados/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg'], 'importado', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench'),
  ('Curl de muñeca invertido con barra', 'Antebrazos', 'Barra', 'Con los antebrazos apoyados en el banco y las palmas hacia abajo, dejá bajar la barra y subila extendiendo las muñecas. Movimiento corto y controlado.', array['importados/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg', 'importados/Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg'], 'importado', 'Palms-Down_Wrist_Curl_Over_A_Bench'),
  ('Curl de muñeca con mancuernas', 'Antebrazos', 'Mancuernas', 'Sentado con los antebrazos apoyados en los muslos y las palmas hacia arriba, flexioná las muñecas subiendo las mancuernas y bajalas lento.', array['importados/Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg', 'importados/Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg'], 'importado', 'Seated_Dumbbell_Palms-Up_Wrist_Curl'),
  ('Curl invertido con barra', 'Antebrazos', 'Barra', 'De pie con la barra en agarre prono (palmas hacia abajo), subila flexionando los codos pegados al cuerpo. Bajala controlada.', array['importados/Reverse_Barbell_Curl/0.jpg', 'importados/Reverse_Barbell_Curl/1.jpg'], 'importado', 'Reverse_Barbell_Curl'),
  ('Sentadilla con barra', 'Cuádriceps', 'Barra', 'Con la barra apoyada en la parte alta de la espalda y los pies al ancho de los hombros, bajá flexionando cadera y rodillas como si te sentaras. Bajá hasta que los muslos queden paralelos al piso y subí empujando con los talones.', array['importados/Barbell_Squat/0.jpg', 'importados/Barbell_Squat/1.jpg'], 'importado', 'Barbell_Squat'),
  ('Sentadilla frontal con barra', 'Cuádriceps', 'Barra', 'Apoyá la barra adelante sobre los hombros con los codos altos. Bajá con el torso erguido hasta que los muslos queden paralelos al piso y subí empujando con los talones.', array['importados/Front_Squat_Clean_Grip/0.jpg', 'importados/Front_Squat_Clean_Grip/1.jpg'], 'importado', 'Front_Squat_Clean_Grip'),
  ('Sentadilla con mancuernas', 'Cuádriceps', 'Mancuernas', 'De pie con una mancuerna en cada mano a los costados, bajá flexionando cadera y rodillas con la espalda recta. Subí empujando con los talones.', array['importados/Dumbbell_Squat/0.jpg', 'importados/Dumbbell_Squat/1.jpg'], 'importado', 'Dumbbell_Squat'),
  ('Sentadilla goblet', 'Cuádriceps', 'Otro', 'Sostené una pesa rusa o mancuerna pegada al pecho con las dos manos. Bajá en sentadilla con el torso erguido y los codos entre las rodillas, y subí empujando con los talones.', array['importados/Goblet_Squat/0.jpg', 'importados/Goblet_Squat/1.jpg'], 'importado', 'Goblet_Squat'),
  ('Sentadilla sin peso', 'Cuádriceps', 'Peso corporal', 'Con los pies al ancho de los hombros y los brazos adelante, bajá como si te sentaras en una silla. Subí empujando con los talones manteniendo la espalda recta.', array['importados/Bodyweight_Squat/0.jpg', 'importados/Bodyweight_Squat/1.jpg'], 'importado', 'Bodyweight_Squat'),
  ('Sentadilla en máquina Smith', 'Cuádriceps', 'Máquina', 'Ubicate con la barra de la Smith en la parte alta de la espalda y los pies un poco adelantados. Destrabala, bajá hasta que los muslos queden paralelos al piso y subí.', array['importados/Smith_Machine_Squat/0.jpg', 'importados/Smith_Machine_Squat/1.jpg'], 'importado', 'Smith_Machine_Squat'),
  ('Sentadilla hack en máquina', 'Cuádriceps', 'Máquina', 'Apoyá la espalda y los hombros en la máquina con los pies al ancho de los hombros. Destrabala, bajá flexionando las rodillas hasta 90° y empujá hasta volver arriba sin bloquearlas.', array['importados/Hack_Squat/0.jpg', 'importados/Hack_Squat/1.jpg'], 'importado', 'Hack_Squat'),
  ('Prensa de piernas', 'Cuádriceps', 'Máquina', 'Sentate con la espalda apoyada y los pies al ancho de los hombros en la plataforma. Bajala flexionando las rodillas hasta 90° y empujá hasta extender las piernas sin bloquearlas.', array['importados/Leg_Press/0.jpg', 'importados/Leg_Press/1.jpg'], 'importado', 'Leg_Press'),
  ('Extensión de cuádriceps (sillón)', 'Cuádriceps', 'Máquina', 'Sentate con la espalda apoyada y los tobillos detrás del rodillo. Extendé las piernas hasta dejarlas rectas, sostené un segundo y bajá lento.', array['importados/Leg_Extensions/0.jpg', 'importados/Leg_Extensions/1.jpg'], 'importado', 'Leg_Extensions'),
  ('Estocadas con barra', 'Cuádriceps', 'Barra', 'Con la barra en la espalda, dá un paso largo hacia adelante y bajá hasta que las dos rodillas queden a 90°. Empujá con la pierna de adelante para volver y alterná.', array['importados/Barbell_Lunge/0.jpg', 'importados/Barbell_Lunge/1.jpg'], 'importado', 'Barbell_Lunge'),
  ('Estocadas con mancuernas', 'Cuádriceps', 'Mancuernas', 'Con una mancuerna en cada mano, dá un paso largo hacia adelante y bajá hasta que la rodilla de atrás casi toque el piso. Volvé empujando con la pierna de adelante y alterná.', array['importados/Dumbbell_Lunges/0.jpg', 'importados/Dumbbell_Lunges/1.jpg'], 'importado', 'Dumbbell_Lunges'),
  ('Estocadas caminando con barra', 'Cuádriceps', 'Barra', 'Con la barra en la espalda, avanzá con pasos largos bajando en cada estocada hasta que la rodilla de atrás casi toque el piso. Alterná las piernas en cada paso.', array['importados/Barbell_Walking_Lunge/0.jpg', 'importados/Barbell_Walking_Lunge/1.jpg'], 'importado', 'Barbell_Walking_Lunge'),
  ('Estocadas hacia atrás con mancuernas', 'Cuádriceps', 'Mancuernas', 'Con una mancuerna en cada mano, dá un paso largo hacia atrás y bajá hasta que las dos rodillas queden a 90°. Volvé a la posición inicial y alterná.', array['importados/Dumbbell_Rear_Lunge/0.jpg', 'importados/Dumbbell_Rear_Lunge/1.jpg'], 'importado', 'Dumbbell_Rear_Lunge'),
  ('Sentadilla dividida con mancuernas', 'Cuádriceps', 'Mancuernas', 'Con una pierna adelante y otra atrás, y una mancuerna en cada mano, bajá en vertical hasta que la rodilla de atrás casi toque el piso. Subí sin mover los pies y cambiá de pierna al terminar.', array['importados/Split_Squat_with_Dumbbells/0.jpg', 'importados/Split_Squat_with_Dumbbells/1.jpg'], 'importado', 'Split_Squat_with_Dumbbells'),
  ('Subidas al banco con mancuernas', 'Cuádriceps', 'Mancuernas', 'Con una mancuerna en cada mano, apoyá un pie en un banco o cajón y subí empujando con esa pierna hasta quedar parado arriba. Bajá controlado y alterná.', array['importados/Dumbbell_Step_Ups/0.jpg', 'importados/Dumbbell_Step_Ups/1.jpg'], 'importado', 'Dumbbell_Step_Ups'),
  ('Sentadilla sumo con mancuerna', 'Cuádriceps', 'Mancuernas', 'Con los pies bien abiertos y las puntas hacia afuera, sostené una mancuerna con las dos manos entre las piernas. Bajá con el torso erguido y subí apretando glúteos.', array['importados/Plie_Dumbbell_Squat/0.jpg', 'importados/Plie_Dumbbell_Squat/1.jpg'], 'importado', 'Plie_Dumbbell_Squat'),
  ('Aductores en máquina', 'Cuádriceps', 'Máquina', 'Sentate en la máquina con las piernas abiertas contra las almohadillas. Cerrá las piernas apretando la cara interna de los muslos y volvé lento.', array['importados/Thigh_Adductor/0.jpg', 'importados/Thigh_Adductor/1.jpg'], 'importado', 'Thigh_Adductor'),
  ('Curl femoral acostado', 'Isquiotibiales', 'Máquina', 'Acostate boca abajo con los tobillos debajo del rodillo. Flexioná las rodillas llevando los talones hacia los glúteos y bajá lento.', array['importados/Lying_Leg_Curls/0.jpg', 'importados/Lying_Leg_Curls/1.jpg'], 'importado', 'Lying_Leg_Curls'),
  ('Curl femoral sentado', 'Isquiotibiales', 'Máquina', 'Sentate con la espalda apoyada y los tobillos sobre el rodillo. Flexioná las rodillas llevando el rodillo hacia abajo y atrás y volvé controlado.', array['importados/Seated_Leg_Curl/0.jpg', 'importados/Seated_Leg_Curl/1.jpg'], 'importado', 'Seated_Leg_Curl'),
  ('Curl femoral de pie', 'Isquiotibiales', 'Máquina', 'De pie en la máquina con el tobillo detrás del rodillo, flexioná la rodilla llevando el talón hacia el glúteo. Bajá lento y cambiá de pierna al terminar.', array['importados/Standing_Leg_Curl/0.jpg', 'importados/Standing_Leg_Curl/1.jpg'], 'importado', 'Standing_Leg_Curl'),
  ('Peso muerto rumano', 'Isquiotibiales', 'Barra', 'De pie con la barra frente a los muslos y las rodillas apenas flexionadas, llevá la cadera hacia atrás bajando la barra pegada a las piernas. Bajá hasta sentir el estiramiento atrás de los muslos y subí empujando la cadera hacia adelante.', array['importados/Romanian_Deadlift/0.jpg', 'importados/Romanian_Deadlift/1.jpg'], 'importado', 'Romanian_Deadlift'),
  ('Peso muerto con piernas rígidas', 'Isquiotibiales', 'Barra', 'Con las piernas casi rectas y la espalda recta, bajá la barra inclinándote desde la cadera hasta sentir el estiramiento en los isquiotibiales. Subí controlado.', array['importados/Stiff-Legged_Barbell_Deadlift/0.jpg', 'importados/Stiff-Legged_Barbell_Deadlift/1.jpg'], 'importado', 'Stiff-Legged_Barbell_Deadlift'),
  ('Peso muerto rumano con mancuernas', 'Isquiotibiales', 'Mancuernas', 'Con una mancuerna en cada mano frente a los muslos, llevá la cadera hacia atrás bajando las mancuernas pegadas a las piernas, con la espalda recta. Subí apretando glúteos.', array['importados/Stiff-Legged_Dumbbell_Deadlift/0.jpg', 'importados/Stiff-Legged_Dumbbell_Deadlift/1.jpg'], 'importado', 'Stiff-Legged_Dumbbell_Deadlift'),
  ('Buenos días con barra', 'Isquiotibiales', 'Barra', 'Con la barra en la espalda y las rodillas apenas flexionadas, inclinate hacia adelante desde la cadera con la espalda recta hasta que el torso quede casi paralelo al piso. Volvé a subir.', array['importados/Stiff_Leg_Barbell_Good_Morning/0.jpg', 'importados/Stiff_Leg_Barbell_Good_Morning/1.jpg'], 'importado', 'Stiff_Leg_Barbell_Good_Morning'),
  ('Hip thrust con barra', 'Glúteos', 'Barra', 'Sentado en el piso con la espalda alta apoyada en un banco y la barra sobre la cadera, empujá la cadera hacia arriba hasta alinear el torso con los muslos. Apretá glúteos arriba y bajá controlado.', array['importados/Barbell_Hip_Thrust/0.jpg', 'importados/Barbell_Hip_Thrust/1.jpg'], 'importado', 'Barbell_Hip_Thrust'),
  ('Puente de glúteos con barra', 'Glúteos', 'Barra', 'Acostado boca arriba con las rodillas flexionadas y la barra sobre la cadera, elevá la cadera apretando glúteos hasta formar una línea recta. Bajá lento.', array['importados/Barbell_Glute_Bridge/0.jpg', 'importados/Barbell_Glute_Bridge/1.jpg'], 'importado', 'Barbell_Glute_Bridge'),
  ('Puente de glúteos', 'Glúteos', 'Peso corporal', 'Acostado boca arriba con las rodillas flexionadas y los pies apoyados, elevá la cadera apretando glúteos hasta alinear rodillas, cadera y hombros. Bajá controlado.', array['importados/Butt_Lift_Bridge/0.jpg', 'importados/Butt_Lift_Bridge/1.jpg'], 'importado', 'Butt_Lift_Bridge'),
  ('Puente de glúteos a una pierna', 'Glúteos', 'Peso corporal', 'Acostado boca arriba con un pie apoyado y la otra pierna extendida, elevá la cadera empujando con el talón apoyado. Bajá lento y cambiá de pierna al terminar.', array['importados/Single_Leg_Glute_Bridge/0.jpg', 'importados/Single_Leg_Glute_Bridge/1.jpg'], 'importado', 'Single_Leg_Glute_Bridge'),
  ('Patada de glúteo en cuadrupedia', 'Glúteos', 'Peso corporal', 'En cuatro apoyos, con la espalda recta, llevá una pierna hacia atrás y arriba con la rodilla flexionada apretando el glúteo. Bajá controlado y cambiá de pierna al terminar.', array['importados/Glute_Kickback/0.jpg', 'importados/Glute_Kickback/1.jpg'], 'importado', 'Glute_Kickback'),
  ('Patada de glúteo en polea', 'Glúteos', 'Polea', 'Con la tobillera enganchada en la polea baja y sosteniéndote de la máquina, llevá la pierna hacia atrás con la rodilla casi recta. Volvé lento y cambiá de pierna al terminar.', array['importados/One-Legged_Cable_Kickback/0.jpg', 'importados/One-Legged_Cable_Kickback/1.jpg'], 'importado', 'One-Legged_Cable_Kickback'),
  ('Pull through en polea', 'Glúteos', 'Polea', 'De espaldas a la polea baja con la soga entre las piernas, llevá la cadera hacia atrás con la espalda recta. Volvé a ponerte de pie empujando la cadera hacia adelante y apretando glúteos.', array['importados/Pull_Through/0.jpg', 'importados/Pull_Through/1.jpg'], 'importado', 'Pull_Through'),
  ('Abductores en máquina', 'Glúteos', 'Máquina', 'Sentate en la máquina con las piernas juntas contra las almohadillas. Abrí las piernas hacia afuera y volvé lento sin que las pesas choquen.', array['importados/Thigh_Abductor/0.jpg', 'importados/Thigh_Abductor/1.jpg'], 'importado', 'Thigh_Abductor'),
  ('Elevación de talones de pie en máquina', 'Pantorrillas', 'Máquina', 'Con los hombros debajo de las almohadillas y la punta de los pies en el escalón, subí sobre las puntas lo más alto que puedas. Bajá lento hasta estirar las pantorrillas.', array['importados/Standing_Calf_Raises/0.jpg', 'importados/Standing_Calf_Raises/1.jpg'], 'importado', 'Standing_Calf_Raises'),
  ('Elevación de talones sentado', 'Pantorrillas', 'Máquina', 'Sentado con las rodillas debajo de la almohadilla y la punta de los pies en el escalón, subí los talones lo más alto posible. Bajá controlado.', array['importados/Seated_Calf_Raise/0.jpg', 'importados/Seated_Calf_Raise/1.jpg'], 'importado', 'Seated_Calf_Raise'),
  ('Gemelos en prensa', 'Pantorrillas', 'Máquina', 'En la prensa, apoyá solo la punta de los pies en el borde de la plataforma con las piernas extendidas. Empujá con las puntas y volvé lento sin flexionar las rodillas.', array['importados/Calf_Press_On_The_Leg_Press_Machine/0.jpg', 'importados/Calf_Press_On_The_Leg_Press_Machine/1.jpg'], 'importado', 'Calf_Press_On_The_Leg_Press_Machine'),
  ('Elevación de talones con mancuernas', 'Pantorrillas', 'Mancuernas', 'De pie con una mancuerna en cada mano, subí sobre las puntas de los pies lo más alto que puedas. Bajá lento. Podés apoyar las puntas en un escalón para más recorrido.', array['importados/Standing_Dumbbell_Calf_Raise/0.jpg', 'importados/Standing_Dumbbell_Calf_Raise/1.jpg'], 'importado', 'Standing_Dumbbell_Calf_Raise'),
  ('Elevación de talones en máquina Smith', 'Pantorrillas', 'Máquina', 'Con la barra de la Smith en la espalda y la punta de los pies sobre un escalón, subí los talones lo más alto que puedas y bajá controlado.', array['importados/Smith_Machine_Calf_Raise/0.jpg', 'importados/Smith_Machine_Calf_Raise/1.jpg'], 'importado', 'Smith_Machine_Calf_Raise'),
  ('Abdominales (crunch)', 'Abdominales', 'Peso corporal', 'Acostado boca arriba con las rodillas flexionadas, subí los hombros del piso contrayendo el abdomen, sin tirar del cuello. Bajá lento.', array['importados/Crunches/0.jpg', 'importados/Crunches/1.jpg'], 'importado', 'Crunches'),
  ('Crunch inverso', 'Abdominales', 'Peso corporal', 'Acostado boca arriba con las piernas flexionadas en el aire, llevá las rodillas hacia el pecho despegando la cadera del piso. Bajá controlado.', array['importados/Reverse_Crunch/0.jpg', 'importados/Reverse_Crunch/1.jpg'], 'importado', 'Reverse_Crunch'),
  ('Plancha', 'Abdominales', 'Peso corporal', 'Apoyá los antebrazos y las puntas de los pies, con el cuerpo en línea recta. Apretá abdomen y glúteos y sostené la posición sin hundir la cadera.', array['importados/Plank/0.jpg', 'importados/Plank/1.jpg'], 'importado', 'Plank'),
  ('Plancha lateral', 'Abdominales', 'Peso corporal', 'De costado, apoyá un antebrazo y el costado del pie, con el cuerpo en línea recta. Sostené la posición sin dejar caer la cadera y cambiá de lado.', array['importados/Side_Bridge/0.jpg', 'importados/Side_Bridge/1.jpg'], 'importado', 'Side_Bridge'),
  ('Crunch en polea', 'Abdominales', 'Polea', 'Arrodillado frente a la polea alta con la soga a los costados de la cabeza, flexioná el torso llevando los codos hacia los muslos. Volvé lento.', array['importados/Cable_Crunch/0.jpg', 'importados/Cable_Crunch/1.jpg'], 'importado', 'Cable_Crunch'),
  ('Crunch en máquina', 'Abdominales', 'Máquina', 'Sentate en la máquina y tomá las manijas. Flexioná el torso hacia adelante contrayendo el abdomen y volvé controlado.', array['importados/Ab_Crunch_Machine/0.jpg', 'importados/Ab_Crunch_Machine/1.jpg'], 'importado', 'Ab_Crunch_Machine'),
  ('Elevación de piernas en banco', 'Abdominales', 'Peso corporal', 'Acostado en un banco y sosteniéndote del borde, elevá las piernas casi rectas hasta la vertical. Bajalas lento sin apoyarlas.', array['importados/Flat_Bench_Lying_Leg_Raise/0.jpg', 'importados/Flat_Bench_Lying_Leg_Raise/1.jpg'], 'importado', 'Flat_Bench_Lying_Leg_Raise'),
  ('Elevación de piernas colgado', 'Abdominales', 'Peso corporal', 'Colgado de la barra, elevá las piernas (rectas o con las rodillas flexionadas) sin balancearte, hasta la altura de la cadera o más. Bajalas controladas.', array['importados/Hanging_Leg_Raise/0.jpg', 'importados/Hanging_Leg_Raise/1.jpg'], 'importado', 'Hanging_Leg_Raise'),
  ('Giros rusos', 'Abdominales', 'Peso corporal', 'Sentado con las rodillas flexionadas y el torso inclinado hacia atrás, girá el torso de un lado al otro llevando las manos hacia cada costado. Podés sumar un peso.', array['importados/Russian_Twist/0.jpg', 'importados/Russian_Twist/1.jpg'], 'importado', 'Russian_Twist'),
  ('Bicho muerto (dead bug)', 'Abdominales', 'Peso corporal', 'Acostado boca arriba con los brazos hacia el techo y las rodillas a 90°, extendé a la vez un brazo y la pierna contraria sin despegar la zona lumbar. Volvé y alterná.', array['importados/Dead_Bug/0.jpg', 'importados/Dead_Bug/1.jpg'], 'importado', 'Dead_Bug'),
  ('Inclinaciones laterales con mancuerna', 'Abdominales', 'Mancuernas', 'De pie con una mancuerna en una mano, inclinate hacia ese costado y volvé a la vertical usando los oblicuos. Cambiá de lado al terminar.', array['importados/Dumbbell_Side_Bend/0.jpg', 'importados/Dumbbell_Side_Bend/1.jpg'], 'importado', 'Dumbbell_Side_Bend'),
  ('Rueda abdominal', 'Abdominales', 'Otro', 'De rodillas, tomá la rueda con las dos manos y rodala hacia adelante estirando el cuerpo sin hundir la zona lumbar. Volvé contrayendo el abdomen.', array['importados/Ab_Roller/0.jpg', 'importados/Ab_Roller/1.jpg'], 'importado', 'Ab_Roller'),
  ('Swing con pesa rusa', 'Cuerpo completo', 'Otro', 'Con la pesa rusa entre las piernas, llevá la cadera hacia atrás y proyectala hacia adelante con fuerza para balancear la pesa hasta la altura del pecho. El impulso sale de la cadera, no de los brazos.', array['importados/One-Arm_Kettlebell_Swings/0.jpg', 'importados/One-Arm_Kettlebell_Swings/1.jpg'], 'importado', 'One-Arm_Kettlebell_Swings'),
  ('Thruster con pesa rusa', 'Cuerpo completo', 'Otro', 'Con la pesa a la altura del hombro, hacé una sentadilla y al subir empujala por encima de la cabeza en un solo movimiento. Bajala al hombro y repetí.', array['importados/Kettlebell_Thruster/0.jpg', 'importados/Kettlebell_Thruster/1.jpg'], 'importado', 'Kettlebell_Thruster'),
  ('Escaladores', 'Cuerpo completo', 'Peso corporal', 'En posición de flexión con los brazos extendidos, llevá una rodilla hacia el pecho y alterná las piernas rápido, como si corrieras, sin levantar la cadera.', array['importados/Mountain_Climbers/0.jpg', 'importados/Mountain_Climbers/1.jpg'], 'importado', 'Mountain_Climbers'),
  ('Peso muerto sumo', 'Cuerpo completo', 'Barra', 'Con los pies bien abiertos y las puntas hacia afuera, tomá la barra con las manos por dentro de las piernas. Con la espalda recta, levantala empujando el piso hasta quedar erguido y bajala controlada.', array['importados/Sumo_Deadlift/0.jpg', 'importados/Sumo_Deadlift/1.jpg'], 'importado', 'Sumo_Deadlift')
